try {
  var input = $input.first().json;
  var msg = (input.body && input.body.message) ? input.body.message : {};

  // Phone — 3 extraction paths (from VAPI WEBHOOK_EVENTS.md)
  var phone = '';
  if (msg.call && msg.call.customer) {
    phone = msg.call.customer.number || msg.call.customer.phoneNumber || '';
  }
  if (!phone && msg.customer) {
    phone = msg.customer.number || '';
  }

  // Caller name — 3-tier cascade
  var name = '';
  if (msg.call && msg.call.customer) {
    name = msg.call.customer.name || '';
  }
  if (!name && msg.summary) {
    var nameMatch = msg.summary.match(/^([A-Z][a-z]+ [A-Z][a-z]+) called/);
    if (nameMatch) name = nameMatch[1];
  }
  if (!name && msg.artifact && msg.artifact.messages) {
    var allMsgs = msg.artifact.messages;
    for (var i = 0; i < allMsgs.length; i++) {
      if (allMsgs[i].toolCalls) {
        for (var j = 0; j < allMsgs[i].toolCalls.length; j++) {
          try {
            var args = JSON.parse(allMsgs[i].toolCalls[j].function.arguments || '{}');
            if (args.callerName) { name = args.callerName; break; }
          } catch(parseErr) {}
        }
      }
      if (name) break;
    }
  }

  // Duration + timestamps (durationSeconds is at TOP LEVEL of message, not inside call)
  var duration = Math.round(msg.durationSeconds || 0);
  var startedAt = msg.startedAt || new Date().toISOString();
  var endedAt = msg.endedAt || new Date().toISOString();

  // Summary and structured data
  var summary = '';
  if (msg.analysis && msg.analysis.summary) summary = msg.analysis.summary;
  if (!summary && msg.summary) summary = msg.summary;
  var structured = (msg.analysis && msg.analysis.structuredData) ? msg.analysis.structuredData : {};

  // Transcript / recording URL
  var transcriptUrl = '';
  if (msg.artifact) {
    transcriptUrl = msg.artifact.recordingUrl || msg.artifact.stereoRecordingUrl || '';
  }

  // Determine outcome from VAPI structured data
  var outcome = 'no-answer';
  if (structured.appointmentBooked === true || structured.appointmentBooked === 'true') {
    outcome = 'booked';
  } else if (structured.callbackRequested === true || structured.callbackRequested === 'true') {
    outcome = 'callback-requested';
  } else if (structured.notInterested === true || structured.notInterested === 'true') {
    outcome = 'not-interested';
  } else if (structured.optOut === true || structured.optOut === 'true') {
    outcome = 'do-not-contact';
  } else if (structured.leftVoicemail === true || structured.leftVoicemail === 'true') {
    outcome = 'voicemail';
  } else if (msg.endedReason === 'voicemail') {
    outcome = 'voicemail';
  } else if (duration > 15) {
    // Real conversation but no specific outcome detected
    outcome = 'called';
  }

  var callId = (msg.call && msg.call.id) ? msg.call.id : '';

  return [{
    json: {
      phone: phone,
      name: name,
      duration: duration,
      startedAt: startedAt,
      endedAt: endedAt,
      summary: summary,
      transcriptUrl: transcriptUrl,
      outcome: outcome,
      callId: callId
    }
  }];

} catch(e) {
  return [{
    json: {
      phone: '',
      name: '',
      duration: 0,
      startedAt: new Date().toISOString(),
      endedAt: new Date().toISOString(),
      summary: '',
      transcriptUrl: '',
      outcome: 'no-answer',
      callId: '',
      parseError: e.message
    }
  }];
}

try {
  var parsed = $('Parse Call Data').first().json;
  var config = $('⚙️ Client Config').first().json;

  var clientRows = $('Read Client Record').all();
  var clientRow = (clientRows && clientRows.length > 0 && clientRows[0].json && clientRows[0].json.Phone) ? clientRows[0].json : {};

  var apptRows = $('Read Appointment Record').all();
  var apptRow = (apptRows && apptRows.length > 0 && apptRows[0].json && apptRows[0].json.Phone) ? apptRows[0].json : {};

  var msgRows = $('Read Messages').all();

  var currentCount = parseInt(clientRow['Call Count'] || '0', 10);
  if (isNaN(currentCount)) currentCount = 0;
  var newCallCount = currentCount + 1;

  var name = parsed.name || clientRow['Name'] || 'Valued Customer';
  var service = apptRow['Service'] || clientRow['Service Interest'] || 'your enquiry';
  var address = apptRow['Address'] || '';

  var existingStatus = clientRow['Status'] || '';
  var statusMap = {
    'booked': 'booked',
    'not-interested': 'not-interested',
    'callback-requested': 'callback-requested',
    'voicemail': 'voicemail',
    'no-answer': 'no-answer',
    'do-not-contact': 'do-not-contact',
    'called': 'called'
  };
  var status;
  if (existingStatus === 'sequence-active' && (parsed.outcome === 'no-answer' || parsed.outcome === 'voicemail')) {
    status = 'sequence-active';
  } else {
    status = statusMap[parsed.outcome] || 'called';
  }

  var upcomingAppointment = '';
  if (parsed.outcome === 'booked' && apptRow['Date'] && apptRow['Time']) {
    upcomingAppointment = apptRow['Date'] + ' at ' + apptRow['Time'];
  } else if (parsed.outcome === 'not-interested' || parsed.outcome === 'do-not-contact') {
    upcomingAppointment = '';
  } else if (clientRow['Upcoming Appointment']) {
    upcomingAppointment = clientRow['Upcoming Appointment'];
  }

  var hasUrgentMessage = false;
  var urgentText = '';
  if (msgRows && msgRows.length > 0) {
    for (var i = 0; i < msgRows.length; i++) {
      var row = msgRows[i].json || {};
      if (row.Urgency === 'urgent' && row.Status === 'new') {
        hasUrgentMessage = true;
        urgentText = row.Message || 'Urgent message received';
        break;
      }
    }
  }

  var smsOptOut = clientRow['SMS Opt-Out'] || 'N';
  if (parsed.outcome === 'do-not-contact') { smsOptOut = 'Y'; }

  var businessName = config.businessName || 'Solarify';
  var smsText = '';

  if (smsOptOut !== 'Y') {
    if (parsed.outcome === 'booked') {
      var apptDate = apptRow['Date'] || 'your scheduled date';
      var timeStr = apptRow['Time'] ? ' at ' + apptRow['Time'] : '';
      var addressStr = address ? ' Our team will visit you at ' + address + '.' : '';
      smsText = 'Hi ' + name + ', your ' + service + ' appointment is confirmed for ' + apptDate + timeStr + '.' + addressStr + ' Reply STOP to opt out. - ' + businessName;
    } else if (parsed.outcome === 'callback-requested') {
      smsText = 'Hi ' + name + ', thanks for your interest! Our team has noted your callback request and will be in touch shortly. Reply STOP to opt out. - ' + businessName;
    } else if (parsed.outcome === 'voicemail') {
      smsText = 'Hi ' + name + ', we just tried reaching you about your ' + service + ' enquiry. When is a good time to call? Reply STOP to opt out. - ' + businessName;
    } else if (parsed.outcome === 'no-answer') {
      smsText = 'Hi ' + name + ", we tried calling you about your " + service + " enquiry but couldn't reach you. We'll try again soon - or feel free to call us back. Reply STOP to opt out. - " + businessName;
    }
  }

  var alertText = hasUrgentMessage
    ? 'URGENT: ' + name + ' (' + parsed.phone + ') left an urgent message: "' + urgentText + '"'
    : '';

  var hasNewMessage = (msgRows && msgRows.length > 0);
  var messageReceiptText = '';
  if (hasNewMessage && parsed.outcome !== 'booked' && smsOptOut !== 'Y') {
    messageReceiptText = 'Hi ' + name + ", thanks for your message. Our team will review it and get back to you shortly. Reply STOP to opt out. - " + businessName;
  }

  var sequenceStartedAt = clientRow['Sequence Started At'] || '';
  if ((parsed.outcome === 'no-answer' || parsed.outcome === 'voicemail') && existingStatus !== 'sequence-active' && !sequenceStartedAt) {
    sequenceStartedAt = new Date().toISOString();
  }

  var callDirection = clientRow['Call Direction'] || 'outbound';

  var processedAt = new Date().toISOString();
  var twilioFrom = config.twilioFromNumber || '';
  var ownerPhone = config.businessOwnerPhone || '';
  var configReady = (twilioFrom.indexOf('PLACEHOLDER') === -1 && ownerPhone.indexOf('PLACEHOLDER') === -1) ? 'Y' : 'N';
  var smsQueued = (smsText !== '' || messageReceiptText !== '') ? 'Y' : 'N';
  var errorNotes = parsed.parseError || '';

  return [{
    json: {
      phone: parsed.phone,
      name: name,
      status: status,
      outcome: parsed.outcome,
      callCount: newCallCount,
      lastContact: parsed.endedAt,
      lastOutcome: parsed.outcome,
      upcomingAppointment: upcomingAppointment,
      transcriptUrl: parsed.transcriptUrl,
      smsOptOut: smsOptOut,
      smsText: smsText,
      alertText: alertText,
      hasUrgentMessage: hasUrgentMessage,
      hasNewMessage: hasNewMessage,
      messageReceiptText: messageReceiptText,
      callId: parsed.callId,
      duration: parsed.duration,
      processedAt: processedAt,
      configReady: configReady,
      smsQueued: smsQueued,
      errorNotes: errorNotes,
      sequenceStartedAt: sequenceStartedAt,
      callDirection: callDirection
    }
  }];

} catch(e) {
  return [{
    json: {
      phone: '',
      name: '',
      status: 'no-answer',
      outcome: 'no-answer',
      callCount: 0,
      lastContact: new Date().toISOString(),
      lastOutcome: 'no-answer',
      upcomingAppointment: '',
      transcriptUrl: '',
      smsOptOut: 'N',
      smsText: '',
      alertText: '',
      hasUrgentMessage: false,
      hasNewMessage: false,
      messageReceiptText: '',
      callId: '',
      duration: 0,
      processedAt: new Date().toISOString(),
      configReady: 'N',
      smsQueued: 'N',
      errorNotes: e.message,
      buildError: e.message,
      sequenceStartedAt: '',
      callDirection: 'outbound'
    }
  }];
}

